from collections import Counter

def transform(grid):
    a=[r[:] for r in grid]; H=len(a); W=len(a[0]); bg=Counter(x for r in a for x in r).most_common(1)[0][0]
    # Long, monochrome vertical lines divide the principal regions.
    seps=[]
    for c in range(W):
        col=[a[r][c] for r in range(H)]; colbg=Counter(col).most_common(1)[0]
        if colbg[0]!=bg and colbg[1]>=H*0.6: seps.append(c)
    bounds=[-1]+seps+[W]
    regions=[]
    for lo,hi in zip(bounds,bounds[1:]):
        c0,c1=lo+1,hi
        if c0>=c1: continue
        sep=a[0][hi] if hi<W else (a[0][lo] if lo>=0 else None)
        r1=H
        for r in range(H):
            if any(a[r][c]!=bg for c in range(c0,c1)):
                # A horizontal separator run at least as wide as this region ends it.
                runs=[]; start=None
                for c in range(W+1):
                    yes=c<W and a[r][c]!=bg and (hi>=W or a[r][c]==sep)
                    if yes and start is None: start=c
                    if not yes and start is not None:
                        if c-start>=c1-c0: runs.append((start,c))
                        start=None
                if runs:
                    # Only horizontal runs made from the divider color count.
                    if any(all(a[r][c]==a[r][runs[0][0]] for c in range(s,e)) and a[r][runs[0][0]]!=bg for s,e in runs):
                        r1=r; break
        regions.append((0,r1,c0,c1))
    def colors_for(box):
        r0,r1,c0,c1=box
        opts=[(0,0,1,1),(0,c1-c0-1,1,-1),(r1-r0-1,0,-1,1),(r1-r0-1,c1-c0-1,-1,-1)]
        best=None
        for rr,cc,dr,dc in opts:
            vals=[]
            for k in range(min(r1-r0,c1-c0)):
                vals.append(a[r0+rr+dr*k][c0+cc+dc*k])
            score=sum(v!=bg and v not in [a[0][s] for s in seps] for v in vals[1:])
            if best is None or score>best[0]: best=(score,vals)
        vals=best[1]
        inds=[i for i,v in enumerate(vals) if v!=bg]
        if not inds: return [bg]
        return vals[:max(inds)+1]
    def paint(out,box):
        r0,r1,c0,c1=box; cs=colors_for(box)
        for r in range(r0,r1):
            for c in range(c0,c1):
                d=min(r-r0,r1-1-r,c-c0,c1-1-c)
                out[r][c]=cs[min(d,len(cs)-1)]
    out=[r[:] for r in a]
    for box in regions: paint(out,box)
    # Closed rectangular outlines are independent nested regions.
    boxes=[]
    for r0 in range(H):
        for c0 in range(W):
            col=a[r0][c0]
            if col==bg: continue
            for c1 in range(c0+2,W+1):
                if a[r0][c1-1]!=col: break
                if c1-c0<3: continue
                for r1 in range(r0+2,H+1):
                    if all(0<=r<H and 0<=c<W and a[r][c]==col for r,c in [(r1-1,c) for c in range(c0,c1)]+[(r,c0) for r in range(r0,r1)]+[(r,c1-1) for r in range(r0,r1)]):
                        boxes.append((r0,r1,c0,c1))
    for box in sorted(set(boxes),key=lambda b:(b[1]-b[0])*(b[3]-b[2])): paint(out,box)
    return out

